changeSet.sql:
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS citizenship   VARCHAR(255);
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS start_date    DATE;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS end_date      DATE;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS duration_text VARCHAR(500);
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS rate_open     BOOLEAN NOT NULL DEFAULT FALSE;

rollback.sql:
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS citizenship;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS start_date;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS end_date;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS duration_text;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS rate_open;

changeSet.sql:
UPDATE krrg_vacancy_sources
SET code = 'SKILLSTAFF', name = 'Skillstaff', updated_at = now()
WHERE code IN ('SKILLSTAF', 'ORDER');

INSERT INTO krrg_vacancy_sources (code, name, created_at, updated_at)
SELECT 'SKILLSTAFF', 'Skillstaff', now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM krrg_vacancy_sources WHERE code = 'SKILLSTAFF');
